// Loaded only in the drug-name reader. All content remains the source PDF text.
window.mountDrugNameFinder = function(){
 const host=document.getElementById('drug-name-finder');
 if(!host||host.dataset.mounted)return;
 host.dataset.mounted='true';
 const input=host.querySelector('#drug-name-search'),status=host.querySelector('#drug-name-status'),results=host.querySelector('#drug-name-results');
 const normal=s=>String(s).normalize('NFKC').toLocaleLowerCase().replace(/[\s\p{P}\p{S}]+/gu,'');
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])).replace(/\n/g,'<br>');
 const entries=window.DRUG_NAME_RECORDS.map(r=>({...r,search:normal(r.values[1]+' '+r.values[r.headers.length===7?3:2])}));
 let timer,composing=false,lastQuery=null,matches=[],shown=0;
 function card(r){return '<section class="drug-name-result"><div class="drug-name-result-top"><h3>'+escape(r.values[1])+'</h3><span>原檔第 '+r.page+' 頁</span></div><dl>'+r.headers.map((h,i)=>'<div><dt>'+escape(h)+'</dt><dd>'+escape(r.values[i])+'</dd></div>').join('')+'</dl><button type="button" data-drug-target="'+r.id+'" data-drug-section="'+r.section+'">前往原表</button></section>'}
 function more(){
  results.querySelector('.drug-name-more')?.remove();
  const batch=matches.slice(shown,shown+30);shown+=batch.length;
  results.insertAdjacentHTML('beforeend',batch.map(card).join(''));
  if(shown<matches.length)results.insertAdjacentHTML('beforeend','<button type="button" class="drug-name-more">顯示更多（剩 '+(matches.length-shown)+' 筆）</button>');
 }
 function search(){
  const q=normal(input.value);if(q===lastQuery)return;lastQuery=q;
  results.replaceChildren();shown=0;
  if(!q){status.textContent='輸入藥名即可查看相關資訊。';matches=[];return}
  matches=entries.filter(r=>r.search.includes(q));
  status.textContent=matches.length?'找到 '+matches.length+' 筆相關資料（含不同分類、劑型及對照表紀錄）。':'找不到符合的藥品，請試試原檔中的學名、商品名或部分藥名。';
  more();
 }
 function schedule(){clearTimeout(timer);if(!composing)timer=setTimeout(search,150)}
 input.addEventListener('input',e=>{if(!e.isComposing)schedule()});
 input.addEventListener('compositionstart',()=>{composing=true;clearTimeout(timer)});
 input.addEventListener('compositionend',()=>{composing=false;schedule()});
 input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!composing&&!e.isComposing){e.preventDefault();clearTimeout(timer);search()}});
 host.querySelector('#drug-name-clear').addEventListener('click',()=>{clearTimeout(timer);input.value='';search();input.focus()});
 results.addEventListener('click',e=>{
  if(e.target.closest('.drug-name-more')){more();return}
  const button=e.target.closest('[data-drug-target]');if(!button)return;
  const target=document.getElementById(button.dataset.drugTarget);if(!target)return;
  document.getElementById('chapter-select').value=button.dataset.drugSection;
  target.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});
  target.setAttribute('tabindex','-1');target.focus({preventScroll:true});
 });
};
